import{_ as d,a0 as p,w as u,s as o,ao as l,I as t,a1 as e,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190129 7 Methods To Identify Disk Partition-FileSystem UUID On Linux","title":"Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法","tag":"201904","desc":""},"relativePath":"201904/20190129 7 Methods To Identify Disk Partition-FileSystem UUID On Linux.md","filePath":"[post].md"}'),r={name:"201904/20190129 7 Methods To Identify Disk Partition-FileSystem UUID On Linux.md"};function c(h,s,b,f,k,U){const n=p("Link");return u(),o("div",null,[s[17]||(s[17]=l(`<h1 id="linux-中獲取硬盤分區或文件系統的-uuid-的七種方法" tabindex="-1">Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法 <a class="header-anchor" href="#linux-中獲取硬盤分區或文件系統的-uuid-的七種方法" aria-label="Permalink to “Linux 中獲取硬盤分區或文件系統的 UUID 的七種方法”">​</a></h1><p>作為一個 Linux 系統管理員，你應該知道如何去查看分區的 UUID 或文件系統的 UUID。因為現在大多數的 Linux 系統都使用 UUID 掛載分區。你可以在 <code>/etc/fstab</code> 文件中可以驗證。</p><p>有許多可用的實用程序可以查看 UUID。本文我們將會向你展示多種查看 UUID 的方法，並且你可以選擇一種適合於你的方法。</p><h3 id="何為-uuid" tabindex="-1">何為 UUID？ <a class="header-anchor" href="#何為-uuid" aria-label="Permalink to “何為 UUID？”">​</a></h3><p>UUID 意即<ruby>通用唯一識別碼<rt>Universally Unique Identifier</rt></ruby>，它可以幫助 Linux 系統識別一個磁盤分區而不是塊設備文件。</p><p>自內核 2.15.1 起，libuuid 就是 util-linux-ng 包中的一部分，它被默認安裝在 Linux 系統中。UUID 由該庫生成，可以合理地認為在一個系統中 UUID 是唯一的，並且在所有系統中也是唯一的。</p><p>這是在計算機系統中用來標識信息的一個 128 位（比特）的數字。UUID 最初被用在<ruby>阿波羅網絡計算機系統<rt>Apollo Network Computing System</rt></ruby>（NCS）中，之後 UUID 被<ruby>開放軟件基金會<rt>Open Software Foundation</rt></ruby>（OSF）標準化，成為<ruby>分佈式計算環境<rt>Distributed Computing Environment</rt></ruby>（DCE）的一部分。</p><p>UUID 以 32 個十六進制的數字表示，被連字符分割為 5 組顯示，總共的 36 個字符的格式為 8-4-4-4-12（32 個字母或數字和 4 個連字符）。</p><p>例如： <code>d92fa769-e00f-4fd7-b6ed-ecf7224af7fa</code></p><p>我的 <code>/etc/fstab</code> 文件示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /etc/fstab: static file system information.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Use &#39;blkid&#39; to print the universally unique identifier for a device; this may</span></span>
<span class="line"><span># be used with UUID= as a more robust way to name devices that works even if</span></span>
<span class="line"><span># disks are added and removed. See fstab(5).</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>UUID=69d9dd18-36be-4631-9ebb-78f05fe3217f / ext4 defaults,noatime 0 1</span></span>
<span class="line"><span>UUID=a2092b92-af29-4760-8e68-7a201922573b swap swap defaults,noatime 0 2</span></span></code></pre></div><p>我們可以使用下面的 7 個命令來查看。</p><ul><li><code>blkid</code> 命令：定位或打印塊設備的屬性。</li><li><code>lsblk</code> 命令：列出所有可用的或指定的塊設備的信息。</li><li><code>hwinfo</code> 命令：硬件信息工具，是另外一個很好的實用工具，用於查詢系統中已存在硬件。</li><li><code>udevadm</code> 命令：udev 管理工具</li><li><code>tune2fs</code> 命令：調整 ext2/ext3/ext4 文件系統上的可調文件系統參數。</li><li><code>dumpe2fs</code> 命令：查詢 ext2/ext3/ext4 文件系統的信息。</li><li>使用 <code>by-uuid</code> 路徑：該目錄下包含有 UUID 和實際的塊設備文件，UUID 與實際的塊設備文件鏈接在一起。</li></ul><h3 id="linux-中如何使用-blkid-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 blkid 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-blkid-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 blkid 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3><p><code>blkid</code> 是定位或打印塊設備屬性的命令列實用工具。它利用 libblkid 庫在 Linux 系統中獲得到磁盤分區的 UUID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># blkid</span></span>
<span class="line"><span>/dev/sda1: UUID=&quot;d92fa769-e00f-4fd7-b6ed-ecf7224af7fa&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;eab59449-01&quot;</span></span>
<span class="line"><span>/dev/sdc1: UUID=&quot;d17e3c31-e2c9-4f11-809c-94a549bc43b7&quot; TYPE=&quot;ext2&quot; PARTUUID=&quot;8cc8f9e5-01&quot;</span></span>
<span class="line"><span>/dev/sdc3: UUID=&quot;ca307aa4-0866-49b1-8184-004025789e63&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;8cc8f9e5-03&quot;</span></span>
<span class="line"><span>/dev/sdc5: PARTUUID=&quot;8cc8f9e5-05&quot;</span></span></code></pre></div><h3 id="linux-中如何使用-lsblk-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 lsblk 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-lsblk-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 lsblk 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3><p><code>lsblk</code> 列出所有有關可用或指定塊設備的信息。<code>lsblk</code> 命令讀取 sysfs 文件系統和 udev 資料庫以收集信息。</p><p>如果 udev 資料庫不可用或者編譯的 lsblk 不支持 udev，它會試圖從塊設備中讀取卷標、UUID 和文件系統類型。這種情況下，必須以 root 身份運行。該命令默認會以類似於樹的格式打印出所有的塊設備（RAM 盤除外）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk -o name,mountpoint,size,uuid</span></span>
<span class="line"><span>NAME   MOUNTPOINT  SIZE UUID</span></span>
<span class="line"><span>sda                 30G </span></span>
<span class="line"><span>└─sda1 /            20G d92fa769-e00f-4fd7-b6ed-ecf7224af7fa</span></span>
<span class="line"><span>sdb                 10G </span></span>
<span class="line"><span>sdc                 10G </span></span>
<span class="line"><span>├─sdc1               1G d17e3c31-e2c9-4f11-809c-94a549bc43b7</span></span>
<span class="line"><span>├─sdc3               1G ca307aa4-0866-49b1-8184-004025789e63</span></span>
<span class="line"><span>├─sdc4               1K </span></span>
<span class="line"><span>└─sdc5               1G </span></span>
<span class="line"><span>sdd                 10G </span></span>
<span class="line"><span>sde                 10G </span></span>
<span class="line"><span>sr0               1024M</span></span></code></pre></div><h3 id="linux-中如何使用-by-uuid-路徑查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 by-uuid 路徑查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-by-uuid-路徑查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 by-uuid 路徑查看磁盤分區或文件系統的 UUID？”">​</a></h3><p>該目錄包含了 UUID 和實際的塊設備文件，UUID 與實際的塊設備文件鏈接在一起。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -lh /dev/disk/by-uuid/</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root 10 Jan 29 08:34 ca307aa4-0866-49b1-8184-004025789e63 -&gt; ../../sdc3</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root 10 Jan 29 08:34 d17e3c31-e2c9-4f11-809c-94a549bc43b7 -&gt; ../../sdc1</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root 10 Jan 29 08:34 d92fa769-e00f-4fd7-b6ed-ecf7224af7fa -&gt; ../../sda1</span></span></code></pre></div><h3 id="linux-中如何使用-hwinfo-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 hwinfo 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-hwinfo-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 hwinfo 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3>`,24)),t("p",null,[e(n,{href:"https://www.2daygeek.com/hwinfo-check-display-detect-system-hardware-information-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("hwinfo",-1)])]),_:1}),s[1]||(s[1]=a(" 意即硬件信息工具，是另外一種很好的實用工具。它被用來檢測系統中已存在的硬件，並且以可讀的格式顯示各種硬件組件的細節信息。",-1))]),s[18]||(s[18]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hwinfo --block | grep by-uuid | awk &#39;{print $3,$7}&#39;</span></span>
<span class="line"><span>/dev/sdc1, /dev/disk/by-uuid/d17e3c31-e2c9-4f11-809c-94a549bc43b7</span></span>
<span class="line"><span>/dev/sdc3, /dev/disk/by-uuid/ca307aa4-0866-49b1-8184-004025789e63</span></span>
<span class="line"><span>/dev/sda1, /dev/disk/by-uuid/d92fa769-e00f-4fd7-b6ed-ecf7224af7fa</span></span></code></pre></div><h3 id="linux-中如何使用-udevadm-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 udevadm 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-udevadm-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 udevadm 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3><p><code>udevadm</code> 需要命令和命令特定的操作。它控制 systemd-udevd 的運行時行為，請求內核事件、管理事件隊列並且提供簡單的調試機制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># udevadm info -q all -n /dev/sdc1 | grep -i by-uuid | head -1</span></span>
<span class="line"><span>S: disk/by-uuid/d17e3c31-e2c9-4f11-809c-94a549bc43b7</span></span></code></pre></div><h3 id="linux-中如何使用-tune2fs-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 tune2fs 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-tune2fs-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 tune2fs 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3><p><code>tune2fs</code> 允許系統管理員在 Linux 的 ext2、ext3、ext4 文件系統中調整各種可調的文件系統參數。這些選項的當前值可以使用選項 <code>-l</code> 顯示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -l /dev/sdc1 | grep UUID</span></span>
<span class="line"><span>Filesystem UUID: d17e3c31-e2c9-4f11-809c-94a549bc43b7</span></span></code></pre></div><h3 id="linux-中如何使用-dumpe2fs-命令查看磁盤分區或文件系統的-uuid" tabindex="-1">Linux 中如何使用 dumpe2fs 命令查看磁盤分區或文件系統的 UUID？ <a class="header-anchor" href="#linux-中如何使用-dumpe2fs-命令查看磁盤分區或文件系統的-uuid" aria-label="Permalink to “Linux 中如何使用 dumpe2fs 命令查看磁盤分區或文件系統的 UUID？”">​</a></h3><p><code>dumpe2fs</code> 打印出現在設備文件系統中的超級塊和塊組的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dumpe2fs /dev/sdc1 | grep UUID</span></span>
<span class="line"><span>dumpe2fs 1.43.5 (04-Aug-2017)</span></span>
<span class="line"><span>Filesystem UUID: d17e3c31-e2c9-4f11-809c-94a549bc43b7</span></span></code></pre></div><hr>`,11)),t("p",null,[s[3]||(s[3]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/check-partitions-uuid-filesystem-uuid-universally-unique-identifier-linux/"},{default:i(()=>[...s[2]||(s[2]=[a("https://www.2daygeek.com/check-partitions-uuid-filesystem-uuid-universally-unique-identifier-linux/",-1)])]),_:1})]),t("p",null,[s[8]||(s[8]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...s[4]||(s[4]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[9]||(s[9]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[5]||(s[5]=[a("lujun9972",-1)])]),_:1}),s[10]||(s[10]=a(" 譯者：",-1)),e(n,{href:"https://github.com/liujing97"},{default:i(()=>[...s[6]||(s[6]=[a("liujing97",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const y=d(r,[["render",c]]);export{m as __pageData,y as default};
